"""Erzeugt videos/003-supermarkt-leer/bilddrehbuch.json aus den echten Satzzeiten (words/w*.json) und der Bildplanung unten.
Jeder Eintrag: (satz-index, zeigt, animation, inhalt, genauigkeit, neugier, [satz_ziffern]). Mehrere Einträge mit gleichem
Index = mehrere Ereignisse im selben Satz (Dauer wird aufgeteilt). 'set' / 'cam' steuern die Renderer-Szene."""
import json, sys
S = json.load(open("saetze.json"))
# Satzdauer inkl. Pause bis zum nächsten Satz (Kapitelwechsel: +1,2 s Kapitelpause im Schnitt)
dur = []
for i, (k, s, e, t) in enumerate(S):
    nxt = S[i+1][1] if i+1 < len(S) and S[i+1][0] == k else e + 0.6
    gap = 1.2 if i+1 < len(S) and S[i+1][0] != k else 0
    dur.append(nxt - s + gap)

D = []   # (i, set, zeigt, animation, inhalt, gen, neugier, ziffern)
def E(i, st, zeigt, anim, inhalt, gen, neu="", z=None): D.append((i, st, zeigt, anim, inhalt, gen, neu, z))

