# ---------- Ausgabe ----------
from collections import Counter
cnt = Counter(i for i, *_ in D)
out = []; t = 0
for i, st, zeigt, anim, inhalt, gen, neu, z in D:
    sek = dur[i] / cnt[i]
    satz = z if z else S[i][3]
    out.append({"satz": satz, "sek": round(sek, 2), "zeigt": zeigt, "animation": anim, "inhalt": inhalt, "genauigkeit": gen,
                "neugier": neu, "kapitel": S[i][0], "set": st, "i": i, "t0": round(t, 2)})
    t += sek
json.dump(out, open(sys.argv[1], "w"), ensure_ascii=False, indent=1)
print(len(out), "Einstellungen", round(t/60, 2), "min")
